          body: "대기기간을 \"7일 뒤에 몰아서 준다\"로 오해하는 경우가 많은데 그렇지 않아요. **그 7일에 대해서는 구직급여를 지급하지 않습니다.** 소정급여일수도 대기기간이 끝난 다음 날부터 계산하기 시작해요.\n\n예외가 하나 뚜렷합니다. 최종 이직 당시 건설일용근로자였던 사람은 대기기간 없이 실업의 신고일부터 계산해 지급받아요. 일이 끊기는 주기가 다른 업종의 사정을 반영한 것입니다.",
