          body: "기한을 놓치지 마세요. **수급기간 안에** 신고해야 합니다. 이미 1년이 지나 버리면 연기할 대상 자체가 없어져요.\n\n구직활동을 억지로 만드는 선택은 피하세요. 질병·부상 등 정신적·육체적 조건으로 통상 취업이 곤란하다고 인정되면 그 기간은 실업이 인정되지 않고, 사실과 다르게 신고하면 부정수급이 됩니다.",
          quote: { law: "고용24 실업급여 안내", text: "\"구직급여는 재취업지원을 위해 지급하는 급여로 임신·출산·질병·부상 등으로 취업 활동이 어려운 경우에는 4년의 범위 내에서 그 기간만큼 수급기간을 연장하여 수급자격자가 불이익을 받지 않도록 하고 있습니다. 수급기간 내에 수급자격증을 첨부하여 고용복지센터에 수급기간연기신고서를 작성하여 제출하시면 됩니다.\"" },
